import { Component, inject, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { ActivatedRoute, Router, RouterLink } from '@angular/router';
import { AuthService } from '../../../../core/services/auth.service';
@Component({selector:'app-reset-password',standalone:true,imports:[FormsModule,RouterLink],template:`<div class="w-full"><p class="eyebrow">Khôi phục tài khoản</p><h1 class="mt-3 font-serif text-4xl font-semibold tracking-tight">Đặt mật khẩu mới</h1><p class="mt-3 text-sm leading-6 text-muted">Nhập email, mã xác minh 6 chữ số và mật khẩu mới.</p><form (submit)="submit($event)" class="mt-7 space-y-4"><label><span class="field-label">Email</span><input class="field" type="email" [(ngModel)]="email" name="email" required/></label><label><span class="field-label">Mã xác minh</span><input class="field tnum" inputmode="numeric" maxlength="6" [(ngModel)]="code" name="code" required/></label><label><span class="field-label">Mật khẩu mới</span><input class="field" type="password" [(ngModel)]="password" name="password" required/></label><label><span class="field-label">Nhập lại mật khẩu</span><input class="field" type="password" [(ngModel)]="confirmPassword" name="confirmPassword" required/></label>@if(message()){<p class="text-sm" [class.text-danger]="error()" [class.text-success]="!error()">{{message()}}</p>}<button class="btn-primary w-full min-h-12" [disabled]="loading()">{{loading()?'Đang lưu...':'Đổi mật khẩu'}}</button><a routerLink="/login" class="block text-center text-sm font-medium text-primary hover:text-primary-dark">Quay lại đăng nhập</a></form></div>`})
export class ResetPasswordComponent{private auth=inject(AuthService);private route=inject(ActivatedRoute);private router=inject(Router);email=this.route.snapshot.queryParamMap.get('email')||'';code='';password='';confirmPassword='';loading=signal(false);message=signal('');error=signal(false);submit(e:Event){e.preventDefault();if(this.password!==this.confirmPassword){this.message.set('Mật khẩu xác nhận không khớp.');this.error.set(true);return;}this.loading.set(true);this.auth.resetPassword({email:this.email,code:this.code,password:this.password,confirmPassword:this.confirmPassword}).subscribe({next:r=>{this.message.set(r.message||'Đổi mật khẩu thành công.');this.error.set(false);this.loading.set(false);setTimeout(()=>this.router.navigate(['/login']),600);},error:e=>{this.message.set(e.error?.message||'Không thể đổi mật khẩu.');this.error.set(true);this.loading.set(false);}});}}